import 'dart:convert';
import 'package:rfc_6901/rfc_6901.dart';

void main() {
  const json = '{"foo": [{"bar": 42}]}';
  final doc = jsonDecode(json);
  final pointer = JsonPointer('/foo/0/bar');
  print(pointer.read(doc)); // 42
  final updated = pointer.write(doc, 'banana');
  print(updated);
}
